106:       }
107: 
108:       const data = (await res.json()) as { text?: string };
109:       const transcribedText = data?.text?.trim();
110:       if (transcribedText) {
111:         setDraft((prev) => (prev ? `${prev.trim()} ${transcribedText}` : transcribedText));
112:         setNotice(null);
