132:       const ctx = new AudioContext();
133:       ctxRef.current = ctx;
134:       const source = ctx.createMediaStreamSource(stream);
135:       const node = ctx.createAnalyser();
136:       node.fftSize = 1024;
137:       node.smoothingTimeConstant = 0.65;
138:       source.connect(node);
139: 
140:       setAnalyser(node);
