233:                     className="flex h-5 w-5 items-center justify-center rounded-[5px] hover:bg-[color-mix(in_srgb,var(--text)_10%,transparent)]"
234:                   >
235:                     <X size={12} strokeWidth={1.5} />
236:                   </button>
